"""Dependency-free interactive operator dashboard."""

DASHBOARD_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project 100 — Trading Console</title>
<style>
:root{--bg:#070b14;--panel:#0d1422;--panel2:#111b2c;--line:#26364f;--text:#eef4ff;--muted:#91a3be;--blue:#5fa8ff;--green:#44d19c;--amber:#ffc768;--red:#ff7187}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,#142747 0,#070b14 42%);color:var(--text);font:14px Inter,ui-sans-serif,system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:24px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:22px}.brand{display:flex;gap:12px;align-items:center}.mark{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,var(--blue),#906dff);display:grid;place-items:center;font-weight:900}.eyebrow,.label{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}h1{font-size:24px;margin:1px 0}.live{display:flex;gap:8px;align-items:center;color:var(--muted)}.dot{width:8px;height:8px;border-radius:50%;background:var(--amber);box-shadow:0 0 15px var(--amber)}.pill,.range button{border:1px solid var(--line);border-radius:999px;background:#0b1321;color:var(--muted);padding:7px 10px}.pill.paper{color:var(--amber);border-color:#7b6132}.range{display:flex;gap:6px}.range button{cursor:pointer}.range button.active{background:var(--blue);border-color:var(--blue);color:#06101e}.grid{display:grid;gap:14px}.metrics{grid-template-columns:repeat(6,minmax(130px,1fr));margin-bottom:14px}.panel,.metric{background:linear-gradient(145deg,rgba(20,31,50,.96),rgba(10,16,28,.96));border:1px solid var(--line);border-radius:14px;box-shadow:0 14px 35px #0003}.metric{padding:16px}.metric b{font-size:21px;display:block;margin-top:6px}.positive{color:var(--green)}.negative{color:var(--red)}.warn{color:var(--amber)}.two{grid-template-columns:1.65fr 1fr;margin-bottom:14px}.panel{padding:17px;min-width:0}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.head h2{font-size:15px;margin:0}.sub{color:var(--muted);font-size:12px}svg{width:100%;height:245px;display:block;overflow:visible}.chart-grid{stroke:#26364f;stroke-width:1}.area{fill:url(#fill);opacity:.3}.line{fill:none;stroke:var(--blue);stroke-width:3}.dd{fill:none;stroke:var(--red);stroke-width:3}.empty{height:245px;display:grid;place-items:center;color:var(--muted);border:1px dashed var(--line);border-radius:10px}.table-wrap{overflow:auto;max-height:330px}table{border-collapse:collapse;width:100%;font-size:13px}th{color:var(--muted);font-weight:600;text-align:left;position:sticky;top:0;background:var(--panel2);cursor:pointer}th,td{padding:11px 8px;border-bottom:1px solid #1d2b41;white-space:nowrap}.tag{font-size:11px;padding:4px 7px;border-radius:6px;background:#1a2a43;color:#b7d7ff}.stream{max-height:330px;overflow:auto}.event{padding:11px 0;border-bottom:1px solid #1d2b41}.event small{color:var(--muted)}.event code{display:block;color:#b9c9e3;white-space:normal;word-break:break-word;margin-top:5px}.broker{border-left:3px solid var(--amber);padding-left:11px}.foot{color:var(--muted);font-size:12px;margin:18px 0 0}@media(max-width:1050px){.metrics{grid-template-columns:repeat(3,1fr)}.two{grid-template-columns:1fr}}@media(max-width:620px){main{padding:14px}.top{align-items:flex-start;flex-direction:column}.metrics{grid-template-columns:repeat(2,1fr)}.metric b{font-size:18px}}
</style></head><body><main><header class="top"><div class="brand"><div class="mark">P</div><div><div class="eyebrow">Autonomous trading console</div><h1>Project 100</h1></div></div><div class="live"><span class="dot"></span><span id="clock">Loading</span><span class="pill paper">PAPER ONLY</span></div></header>
<section class="grid metrics" id="metrics"></section><section class="grid two"><article class="panel"><div class="head"><div><h2>Equity curve</h2><div class="sub">Recorded paper-account snapshots</div></div><div class="range" aria-label="Equity period"><button data-range="1">1D</button><button data-range="7">1W</button><button data-range="30">1M</button><button class="active" data-range="all">All</button></div></div><div id="equity"></div></article><article class="panel"><div class="head"><div><h2>Drawdown</h2><div class="sub">From recorded high-water mark</div></div></div><div id="drawdown"></div></article></section>
<section class="grid two"><article class="panel"><div class="head"><div><h2>Strategy scorecard</h2><div class="sub">Historical paper results only; not a forecast</div></div></div><div class="table-wrap"><table><thead><tr><th>Strategy</th><th>Trades</th><th>Win rate</th><th>Realized P&L</th><th>R total</th></tr></thead><tbody id="strategies"></tbody></table></div></article><article class="panel"><div class="head"><div><h2>Broker & safety</h2><div class="sub">Connection and execution boundary</div></div></div><div id="broker" class="broker">Loading</div><div id="safety" class="event"></div></article></section>
<section class="grid two"><article class="panel"><div class="head"><div><h2>Trade blotter</h2><div class="sub">Closed simulated trades</div></div></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Symbol</th><th>Strategy</th><th>Exit</th><th>P&L</th><th>R</th></tr></thead><tbody id="trades"></tbody></table></div></article><article class="panel"><div class="head"><div><h2>Audit stream</h2><div class="sub">Latest append-only events</div></div></div><div id="events" class="stream"></div></article></section><p class="foot">This dashboard displays simulated engineering replay records. It has no live market data, live orders, or performance projections.</p></main>
<script>
const $=s=>document.querySelector(s), money=n=>typeof n==='number'?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n):'—', pct=n=>typeof n==='number'?(n*100).toFixed(2)+'%':'—', esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let range='all',last={};
function chart(el,rows,key,klass){if(!rows.length)return el.innerHTML='<div class="empty">No recorded history yet</div>';const vals=rows.map(x=>x[key]),lo=Math.min(...vals),hi=Math.max(...vals),span=hi-lo||1,w=900,h=245,p=14,pts=vals.map((v,i)=>`${p+i*(w-2*p)/Math.max(vals.length-1,1)},${h-p-(v-lo)*(h-2*p)/span}`).join(' ');el.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${key} chart"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#5fa8ff"/><stop offset="1" stop-color="#5fa8ff" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M14 45H886M14 120H886M14 200H886"/><polyline class="${klass}" points="${pts}"/></svg>`}
function render(){const {status,performance,activity,broker,insights}=last,cut=range==='all'?0:Date.now()-Number(range)*864e5,curve=(insights.equity_curve||[]).filter(x=>!cut||new Date(x.timestamp).getTime()>=cut);const s=performance.overall||{};$('#metrics').innerHTML=[['Equity',money(status.equity),''],['Realized P&L',money(status.realized_pnl),status.realized_pnl>=0?'positive':'negative'],['Max drawdown',pct(status.max_drawdown),'negative'],['Closed trades',s.sample_size??0,''],['Win rate',pct(s.win_rate),''],['Data freshness',status.data_age_seconds==null?'—':status.data_age_seconds.toFixed(0)+' sec',status.ready?'positive':'warn']].map(([a,b,c])=>`<article class="metric"><div class="label">${a}</div><b class="${c}">${esc(b)}</b></article>`).join('');chart($('#equity'),curve,'equity','line');chart($('#drawdown'),curve,'drawdown','dd');$('#strategies').innerHTML=(insights.strategy_breakdown||[]).map(x=>`<tr><td><span class="tag">${esc(x.strategy)}</span></td><td>${x.trades}</td><td>${pct(x.win_rate)}</td><td class="${x.pnl>=0?'positive':'negative'}">${money(x.pnl)}</td><td>${x.r_total.toFixed(2)}</td></tr>`).join('')||'<tr><td colspan="5">No closed paper trades yet.</td></tr>';$('#trades').innerHTML=(insights.closed_trades||[]).slice().reverse().map(x=>`<tr><td>${new Date(x.timestamp+'Z').toLocaleString()}</td><td><b>${esc(x.symbol)}</b></td><td>${esc(x.strategy)}</td><td>${esc(x.exit_reason||'—')}</td><td class="${x.pnl>=0?'positive':'negative'}">${money(x.pnl)}</td><td>${x.r_multiple==null?'—':x.r_multiple.toFixed(2)}</td></tr>`).join('')||'<tr><td colspan="6">No closed paper trades yet.</td></tr>';$('#events').innerHTML=(activity.events||[]).map(x=>`<div class="event"><b>${esc(x.type)}</b> <small>${new Date(x.timestamp+'Z').toLocaleString()}</small><code>${esc(JSON.stringify(x.payload))}</code></div>`).join('')||'No events yet.';$('#broker').innerHTML=`<b class="${broker.connected?'positive':'warn'}">${broker.connected?'Connected':'Not connected'}</b><p>${esc(broker.reason)}</p><a href="${esc(broker.setup_url)}" target="_blank" rel="noreferrer">Robinhood setup</a>`;$('#safety').innerHTML=`<b>${esc(status.ready?'Paper feed current':'Paper feed awaiting fresh data')}</b><br><small>Live trading remains disabled. ${esc(status.stage?.reasons?.join(', ')||'')}</small>`;$('#clock').textContent='Updated '+new Date().toLocaleTimeString()}
async function refresh(){try{const [status,performance,activity,broker,insights]=await Promise.all(['/paper/status','/paper/performance','/paper/activity','/brokers/robinhood/status','/paper/insights'].map(u=>fetch(u).then(r=>r.json())));last={status,performance,activity,broker,insights};render()}catch(e){$('#events').textContent='Dashboard refresh failed: '+e.message}}document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{range=b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===b));render()});refresh();setInterval(refresh,1000);
</script></body></html>'''
